-- Czech Republic deep-dive ES/DE/FR translations (completing 309).
-- INSERT OR IGNORE throughout.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Emisión B2G voluntaria, sin mandato B2B — pero con una reactivación real del reporte de ventas B2C prevista para 2027', 'Esta página de análisis refleja la orientación pública y las noticias disponibles a principios de agosto de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. La República Checa no tiene un calendario confirmado para un mandato nacional de facturación electrónica B2B ni de emisión B2G en el momento de redactar esto, y la aprobación en el Senado y la firma presidencial de EET 2.0 seguían pendientes — confirme el estado actual directamente con el Ministerio de Hacienda o el Ministerio de Desarrollo Regional antes de basarse en ella.', 'La República Checa completó un modesto despliegue de facturación electrónica B2G, solo de recepción, en octubre de 2016 y nunca ha propuesto un mandato nacional B2B. Lo que hace que la historia de este país merezca la pena seguir no tiene nada que ver con la facturación: un régimen reactivado de Registro Electrónico de Ventas (EET 2.0) — reporte en tiempo real de las ventas presenciales B2C — ya ha sido aprobado por la Cámara de Diputados y se dirige al Senado y a la firma presidencial, con una fecha de entrada en vigor confirmada del 1 de enero de 2027. La única fecha firme que se aplica con independencia de todo esto sigue siendo el suelo transfronterizo de ViDA de toda la UE, del 1 de julio de 2030.', 'Cuando se intercambian facturas electrónicas con organismos públicos checos, los formatos aceptados son EDIFACT, UBL 2.1 y el estándar nacional ISDOC, normalmente a través del portal Národní elektronický nástroj (NEN) — sin ningún paso de validación o aprobación en tiempo real.', 'La única obligación de facturación electrónica exigible en la República Checa hoy en día va en una sola dirección: los poderes adjudicadores públicos (centrales, regionales y locales) deben aceptar y procesar facturas electrónicas conformes de los proveedores que decidan enviarlas. Nada obliga a un proveedor a enviar realmente una, y no existe ningún mandato B2B en absoluto. Por separado — y este es el desarrollo genuinamente en marcha —, EET 2.0 exigirá el reporte en tiempo real de las ventas presenciales B2C a partir del 1 de enero de 2027, una obligación de reporte en el punto de venta, no un mandato de facturación.', 'Sin ningún mandato nacional B2B o de emisión B2G en vigor o previsto, el trabajo relevante de la mayoría de las empresas se divide en dos frentes: la preparación para la facturación electrónica (entender que la obligación de recepción existe solo en el lado gubernamental) y, si su negocio es de comercio minorista, hostelería o servicios presenciales, la preparación real para la exigencia de reporte de ventas en tiempo real de EET 2.0 que llega en 2027.', 'No existe hoy un régimen sancionador de facturación electrónica nacional en la República Checa, por la simple razón de que no existe un mandato nacional de facturación electrónica para los proveedores que puedan incumplir. EET 2.0 es un asunto distinto: su obligación de reporte de ventas en el punto de venta conlleva sanciones de hasta 500.000 CZK por incumplimiento una vez entre en vigor — una multa real, pero por un fallo en el reporte de ventas, no de facturación.', 'La República Checa transpuso la Directiva 2014/55/UE de la UE mediante la Ley n.º 134/2016 Coll. de Contratación Pública (artículo 221), exigiendo que los poderes adjudicadores públicos acepten facturas electrónicas conformes con EN 16931 desde el 1 de octubre de 2016, en formato EDIFACT, UBL 2.1 o el formato nacional ISDOC a través del portal NEN. La emisión por parte de los proveedores ha seguido siendo voluntaria en todo momento, y nunca se ha propuesto un mandato nacional B2B. Por separado, un régimen reactivado de Registro Electrónico de Ventas (EET 2.0) — reporte en tiempo real de las ventas presenciales B2C, no un mandato de facturación B2B — ha sido aprobado por la Cámara de Diputados y está a la espera de la aprobación del Senado y la firma presidencial, con una fecha de entrada en vigor confirmada del 1 de enero de 2027, una exención para los pequeños autónomos con tributación a tanto alzado con una facturación anual inferior a 1.000.000 CZK, y sanciones de hasta 500.000 CZK. El mandato de ViDA de facturación electrónica y reporte transfronterizos B2B es derecho de la UE confirmado desde el 1 de julio de 2030, con independencia de cualquier futura decisión nacional checa.', '🇨🇿' FROM countries WHERE name_en = 'Czech Republic';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Freiwillige B2G-Ausstellung, keine B2B-Pflicht — aber eine echte Wiederbelebung der B2C-Umsatzmeldung ab 2027', 'Diese Länderanalyse spiegelt öffentlich verfügbare Hinweise und Berichterstattung mit Stand Anfang August 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Tschechien hat zum Zeitpunkt der Abfassung keinen bestätigten Zeitplan für eine inländische B2B- oder B2G-Ausstellungspflicht, und die Verabschiedung im Senat sowie die Unterschrift des Präsidenten für EET 2.0 standen noch aus — bestätigen Sie den aktuellen Stand direkt beim Finanzministerium oder beim Ministerium für regionale Entwicklung, bevor Sie darauf aufbauen.', 'Tschechien schloss bis Oktober 2016 eine bescheidene, reine Empfangspflicht für die B2G-E-Rechnung ab und hat nie eine inländische B2B-Pflicht vorgeschlagen. Was die Geschichte dieses Landes beobachtenswert macht, hat nichts mit der Rechnungsstellung zu tun: Ein wiederbelebtes Regime der elektronischen Umsatzregistrierung (EET 2.0) — Echtzeitmeldung persönlicher B2C-Verkäufe — hat das Abgeordnetenhaus bereits passiert und geht nun an den Senat und zur Unterschrift des Präsidenten, mit einem bestätigten Inkrafttretensdatum vom 1. Januar 2027. Das einzig feste Datum, das unabhängig davon gilt, bleibt die EU-weite ViDA-Untergrenze für grenzüberschreitende Umsätze vom 1. Juli 2030.', 'Wo E-Rechnungen mit tschechischen öffentlichen Stellen ausgetauscht werden, sind die akzeptierten Formate EDIFACT, UBL 2.1 und der nationale ISDOC-Standard, meist über das Portal Národní elektronický nástroj (NEN) — ohne jede Freigabe- oder Echtzeitprüfung.', 'Die einzige durchsetzbare E-Rechnungspflicht in Tschechien verläuft heute in eine Richtung: Öffentliche Auftraggeber (zentral, regional und lokal) müssen konforme E-Rechnungen von Lieferanten annehmen und verarbeiten, die sich dafür entscheiden, eine zu senden. Nichts verpflichtet einen Lieferanten, tatsächlich eine zu versenden, und es gibt überhaupt keine B2B-Pflicht. Getrennt davon — und das ist die tatsächlich laufende Entwicklung — wird EET 2.0 ab dem 1. Januar 2027 die Echtzeitmeldung persönlicher B2C-Verkäufe verlangen, eine Meldepflicht am Point of Sale statt einer Rechnungspflicht.', 'Da derzeit keine inländische B2B- oder B2G-Ausstellungspflicht in Kraft oder geplant ist, teilt sich die relevante Arbeit der meisten Unternehmen in zwei Bereiche: Vorbereitung auf die E-Rechnung (verstehen, dass die Empfangspflicht nur auf staatlicher Seite besteht) und, falls Sie stationären Einzelhandel, Gastgewerbe oder Dienstleistungen betreiben, echte Vorbereitung auf die 2027 kommende Echtzeit-Umsatzmeldepflicht von EET 2.0.', 'Es gibt heute kein inländisches E-Rechnungs-Sanktionsregime in Tschechien, aus dem einfachen Grund, dass es keine inländische E-Rechnungspflicht für Lieferanten gibt, gegen die verstoßen werden könnte. EET 2.0 ist eine andere Angelegenheit: Seine Point-of-Sale-Meldepflicht sieht bei Nichteinhaltung Strafen von bis zu 500.000 CZK vor, sobald sie in Kraft tritt — eine echte Strafe, aber für einen Verstoß gegen die Umsatzmeldung, nicht gegen die Rechnungsstellung.', 'Tschechien setzte die EU-Richtlinie 2014/55/EU mit dem Gesetz Nr. 134/2016 Coll. über die öffentliche Auftragsvergabe (Abschnitt 221) um und verlangt seit dem 1. Oktober 2016 von öffentlichen Auftraggebern, EN-16931-konforme E-Rechnungen in EDIFACT, UBL 2.1 oder dem nationalen ISDOC-Format über das NEN-Portal anzunehmen. Die Ausstellung durch Lieferanten blieb durchgehend freiwillig, und eine inländische B2B-Pflicht wurde nie vorgeschlagen. Getrennt davon hat ein wiederbelebtes Regime der elektronischen Umsatzregistrierung (EET 2.0) — Echtzeitmeldung persönlicher B2C-Verkäufe, keine B2B-Rechnungspflicht — das Abgeordnetenhaus passiert und wartet auf die Verabschiedung im Senat und die Unterschrift des Präsidenten, mit einem bestätigten Inkrafttretensdatum vom 1. Januar 2027, einer Befreiung für kleine Pauschalsteuerpflichtige mit einem Jahresumsatz unter 1.000.000 CZK und Strafen von bis zu 500.000 CZK. ViDAs grenzüberschreitende B2B-E-Rechnungs- und Meldepflicht ist ab dem 1. Juli 2030 bestätigtes EU-Recht, unabhängig von einer künftigen tschechischen inländischen Entscheidung.', '🇨🇿' FROM countries WHERE name_en = 'Czech Republic';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Émission B2G volontaire, aucune obligation B2B — mais une véritable relance de la déclaration des ventes B2C prévue pour 2027', 'Cette analyse par pays reflète les informations publiques et l''actualité disponibles début août 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. La République tchèque n''a aucun calendrier confirmé pour une obligation nationale de facturation électronique B2B ou d''émission B2G au moment de la rédaction, et l''adoption par le Sénat ainsi que la signature présidentielle d''EET 2.0 restaient en attente — confirmez le statut actuel directement auprès du ministère des Finances ou du ministère du Développement régional avant de vous y fier.', 'La République tchèque a achevé d''ici octobre 2016 un déploiement modeste, uniquement en réception, de la facturation électronique B2G et n''a jamais proposé d''obligation nationale B2B. Ce qui rend l''histoire de ce pays digne d''intérêt n''a rien à voir avec la facturation : un régime relancé d''enregistrement électronique des ventes (EET 2.0) — déclaration en temps réel des ventes B2C en personne — a déjà été adopté par la Chambre des députés et se dirige vers le Sénat et la signature présidentielle, avec une date d''entrée en vigueur confirmée au 1er janvier 2027. La seule date ferme qui s''applique indépendamment de tout cela reste le plancher transfrontalier ViDA à l''échelle de l''UE, au 1er juillet 2030.', 'Lorsque des factures électroniques sont échangées avec des organismes publics tchèques, les formats acceptés sont l''EDIFACT, l''UBL 2.1 et la norme nationale ISDOC, généralement via le portail Národní elektronický nástroj (NEN) — sans aucune étape de validation ou d''approbation en temps réel.', 'La seule obligation de facturation électronique exécutoire en République tchèque aujourd''hui va dans un seul sens : les pouvoirs adjudicateurs publics (centraux, régionaux et locaux) doivent accepter et traiter les factures électroniques conformes des fournisseurs qui choisissent d''en envoyer une. Rien n''oblige un fournisseur à en envoyer réellement une, et il n''existe aucune obligation B2B d''aucune sorte. Par ailleurs — et c''est le développement véritablement en cours — EET 2.0 exigera la déclaration en temps réel des ventes B2C en personne à partir du 1er janvier 2027, une obligation de déclaration au point de vente plutôt qu''une obligation de facturation.', 'En l''absence de toute obligation nationale B2B ou d''émission B2G actuellement en vigueur ou prévue, le travail pertinent de la plupart des entreprises se divise en deux volets : la préparation à la facturation électronique (comprendre que l''obligation de réception n''existe que côté gouvernemental) et, si vous exercez dans le commerce de détail, l''hôtellerie-restauration ou les services en personne, la préparation réelle à l''exigence de déclaration des ventes en temps réel d''EET 2.0 attendue en 2027.', 'Il n''existe aujourd''hui aucun régime de sanctions national de facturation électronique en République tchèque, pour la simple raison qu''il n''existe aucune obligation nationale de facturation électronique pour les fournisseurs qui pourrait être enfreinte. EET 2.0 est une question distincte : son obligation de déclaration des ventes au point de vente entraîne des sanctions pouvant atteindre 500 000 CZK en cas de non-conformité une fois en vigueur — une amende réelle, mais pour un manquement à la déclaration des ventes, non à la facturation.', 'La République tchèque a transposé la directive européenne 2014/55/UE via la loi n° 134/2016 Coll. relative aux marchés publics (article 221), exigeant depuis le 1er octobre 2016 que les pouvoirs adjudicateurs publics acceptent des factures électroniques conformes à l''EN 16931 au format EDIFACT, UBL 2.1 ou au format national ISDOC via le portail NEN. L''émission par les fournisseurs est restée volontaire tout au long, et aucune obligation nationale B2B n''a jamais été proposée. Par ailleurs, un régime relancé d''enregistrement électronique des ventes (EET 2.0) — déclaration en temps réel des ventes B2C en personne, non une obligation de facturation B2B — a été adopté par la Chambre des députés et attend l''adoption par le Sénat et la signature présidentielle, avec une date d''entrée en vigueur confirmée au 1er janvier 2027, une exemption pour les petits entrepreneurs au régime forfaitaire dont le chiffre d''affaires annuel est inférieur à 1 000 000 CZK, et des sanctions pouvant atteindre 500 000 CZK. L''obligation ViDA de facturation électronique et de déclaration transfrontalières B2B est un droit de l''UE confirmé à partir du 1er juillet 2030, indépendamment de toute future décision nationale tchèque.', '🇨🇿' FROM countries WHERE name_en = 'Czech Republic';

