INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formato y estándar', '[["Estándar", "EN 16931, la norma europea de facturación electrónica"], ["Sintaxis aceptadas", "EDIFACT, UBL 2.1 y el estándar nacional ISDOC"], ["Base legal", "Ley n.º 134/2016 Coll. de Contratación Pública (artículo 221), que transpone la Directiva 2014/55/UE de la UE"], ["B2B hoy", "Sin mandato; acuerdo bilateral entre socios comerciales cuando se usa"]]', 'ISDOC es el único elemento genuinamente checo aquí — un formato nacional de factura XML anterior a la directiva de la UE —, pero coexiste junto a EN 16931/UBL 2.1 en lugar de sustituirlo; nada obliga a una empresa a usarlo específicamente.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Format & Standard', '[["Standard", "EN 16931, die europäische Norm für E-Rechnung"], ["Akzeptierte Syntaxen", "EDIFACT, UBL 2.1 und der nationale ISDOC-Standard"], ["Rechtsgrundlage", "Gesetz Nr. 134/2016 Coll. über die öffentliche Auftragsvergabe (Abschnitt 221), Umsetzung der EU-Richtlinie 2014/55/EU"], ["B2B heute", "Keine Pflicht; bilaterale Vereinbarung zwischen Handelspartnern, sofern überhaupt genutzt"]]', 'ISDOC ist hier das einzig genuin tschechische Element — ein nationales XML-Rechnungsformat, das älter ist als die EU-Richtlinie — steht aber neben EN 16931/UBL 2.1, statt es zu ersetzen; nichts verpflichtet ein Unternehmen, gerade dieses zu nutzen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Format et norme', '[["Norme", "EN 16931, la norme européenne sur la facturation électronique"], ["Syntaxes acceptées", "EDIFACT, UBL 2.1 et la norme nationale ISDOC"], ["Base légale", "Loi n° 134/2016 Coll. relative aux marchés publics (article 221), transposant la directive européenne 2014/55/UE"], ["B2B aujourd''hui", "Aucune obligation ; accord bilatéral entre partenaires commerciaux lorsqu''il est utilisé"]]', 'L''ISDOC est ici le seul élément véritablement tchèque — un format de facture XML national antérieur à la directive européenne — mais il coexiste avec l''EN 16931/UBL 2.1 plutôt que de le remplacer ; rien n''oblige une entreprise à l''utiliser spécifiquement.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'file_format' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Identificadores y registro', '[["Recepción B2G", "No se necesita registro — es una obligación de los poderes adjudicadores públicos, no de los proveedores"], ["Canal de emisión voluntaria", "Portal Národní elektronický nástroj (NEN)"], ["Organismo regulador", "Ministerio de Desarrollo Regional (plataforma NEN); Ministerio de Hacienda (política fiscal)"], ["B2B hoy", "No existe registro — no hay nada para lo que registrarse"]]', 'Como no existe un mandato de emisión, genuinamente no hay ningún paso de registro que una empresa típica deba completar — la obligación promulgada hasta ahora se aplica enteramente al lado de la recepción, y recae en los poderes adjudicadores públicos, no en los proveedores.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Kennungen & Registrierung', '[["B2G-Empfang", "Keine Registrierung nötig — dies ist eine Pflicht öffentlicher Auftraggeber, nicht der Lieferanten"], ["Freiwilliger Ausstellungskanal", "Portal Národní elektronický nástroj (NEN)"], ["Aufsichtsbehörde", "Ministerium für regionale Entwicklung (NEN-Plattform); Finanzministerium (Steuerpolitik)"], ["B2B heute", "Keine Registrierung vorhanden — es gibt nichts, wofür man sich registrieren müsste"]]', 'Da es keine Ausstellungspflicht gibt, gibt es für ein typisches Unternehmen tatsächlich keinen Registrierungsschritt zu erledigen — die bisher erlassene Pflicht betrifft ausschließlich die Empfangsseite und liegt bei öffentlichen Auftraggebern, nicht bei Lieferanten.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Identifiants et enregistrement', '[["Réception B2G", "Aucun enregistrement nécessaire — il s''agit d''une obligation des pouvoirs adjudicateurs publics, non des fournisseurs"], ["Canal d''émission volontaire", "Portail Národní elektronický nástroj (NEN)"], ["Organisme de contrôle", "Ministère du Développement régional (plateforme NEN) ; ministère des Finances (politique fiscale)"], ["B2B aujourd''hui", "Aucun enregistrement n''existe — il n''y a rien à quoi s''inscrire"]]', 'Comme il n''existe aucune obligation d''émission, il n''y a véritablement aucune étape d''enregistrement à accomplir pour une entreprise typique — l''obligation adoptée à ce jour s''applique entièrement du côté de la réception, et incombe aux pouvoirs adjudicateurs publics, non aux fournisseurs.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'file_format' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Contenido obligatorio', '[["Cuando se usa", "Modelo básico completo de EN 16931, o el propio conjunto de campos de ISDOC"], ["Campos obligatorios", "Ninguno especificado más allá de la propia norma, ya que no existe un mandato nacional que defina requisitos adicionales"], ["Archivo", "Se aplican los requisitos estándar checos de conservación de registros"]]', 'Sin un mandato nacional que especifique campos nacionales adicionales, una factura electrónica checa es simplemente un documento estándar EN 16931 o ISDOC — nada extra que aprender más allá de elegir un formato que ambas partes puedan leer.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichtinhalte', '[["Bei Verwendung", "Vollständiges EN-16931-Kernrechnungsmodell oder das eigene Feldset von ISDOC"], ["Pflichtfelder", "Keine über die Norm selbst hinaus festgelegt, da es keine inländische Pflicht gibt, die zusätzliche Anforderungen definiert"], ["Archivierung", "Es gelten die tschechischen Standard-Aufbewahrungspflichten"]]', 'Ohne inländische Pflicht, die zusätzliche nationale Felder festlegt, ist eine tschechische E-Rechnung schlicht ein Standard-EN-16931- oder ISDOC-Dokument — nichts Zusätzliches zu lernen, außer ein Format zu wählen, das beide Seiten lesen können.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Contenu obligatoire', '[["Lorsqu''il est utilisé", "Modèle de base complet EN 16931, ou le propre jeu de champs d''ISDOC"], ["Champs obligatoires", "Aucun spécifié au-delà de la norme elle-même, car il n''existe pas d''obligation nationale définissant des exigences supplémentaires"], ["Archivage", "Les exigences standard tchèques de conservation des documents s''appliquent"]]', 'Sans obligation nationale précisant des champs nationaux supplémentaires, une facture électronique tchèque est simplement un document EN 16931 ou ISDOC standard — rien de plus à apprendre, hormis choisir un format que les deux parties peuvent lire.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'file_format' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Modelo de red', '[["Modelo de facturación", "Sin ningún régimen de validación o reporte de facturas en tiempo real"], ["Canal B2G", "Portal NEN, para los proveedores que elijan enviar electrónicamente"], ["Canal B2B", "Acuerdo bilateral, cuando se usa"], ["EET 2.0 (aparte)", "Reporte en tiempo real en el punto de venta a la Administración Tributaria, desde 2027 — no es un canal de facturación"]]', 'Merece la pena mantener estos dos sistemas separados mentalmente: nada en EET 2.0 cambia cómo se mueve una factura entre empresas, porque EET 2.0 no trata en absoluto de facturas, sino de reportar la venta subyacente en la caja.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Netzwerkmodell', '[["Rechnungsmodell", "Kein Freigabe- oder Echtzeit-Rechnungsmelderegime jeglicher Art"], ["B2G-Kanal", "NEN-Portal, für Lieferanten, die sich für den elektronischen Versand entscheiden"], ["B2B-Kanal", "Bilaterale Vereinbarung, sofern überhaupt genutzt"], ["EET 2.0 (getrennt)", "Echtzeit-Meldung am Point of Sale an die Steuerverwaltung, ab 2027 — kein Rechnungskanal"]]', 'Es lohnt sich, diese beiden Systeme gedanklich getrennt zu halten: An der Bewegung einer Rechnung zwischen Unternehmen ändert EET 2.0 nichts, weil es dabei überhaupt nicht um Rechnungen geht — sondern um die Meldung des zugrunde liegenden Verkaufs an der Kasse.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Modèle de réseau', '[["Modèle de facturation", "Aucun régime de validation ou de déclaration de factures en temps réel"], ["Canal B2G", "Portail NEN, pour les fournisseurs qui choisissent d''envoyer électroniquement"], ["Canal B2B", "Accord bilatéral, lorsqu''il est utilisé"], ["EET 2.0 (distinct)", "Déclaration en temps réel au point de vente à l''administration fiscale, à partir de 2027 — pas un canal de facturation"]]', 'Il vaut la peine de garder ces deux systèmes mentalement distincts : rien dans EET 2.0 ne change la façon dont une facture circule entre entreprises, car EET 2.0 ne concerne pas du tout les factures — il s''agit de déclarer la vente sous-jacente à la caisse.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Lo que realmente es obligatorio hoy', '[["Poderes adjudicadores públicos", "Deben aceptar y procesar facturas electrónicas conformes (desde el 1 de octubre de 2016)"], ["Proveedores del gobierno", "Sin obligación de emisión"], ["Empresas privadas (facturación B2B/B2C)", "Ninguna obligación de ningún tipo"], ["Ventas presenciales B2C (desde 2027)", "Reporte en tiempo real bajo EET 2.0 — una obligación de registro de ventas, no de facturación"]]', 'Merece la pena ser precisos aquí: la República Checa nunca ha exigido que nadie envíe una factura electrónica — solo que ciertos organismos públicos sean capaces de aceptar una, y, por separado y desde 2027, que las ventas presenciales se reporten en tiempo real.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Was heute tatsächlich verpflichtend ist', '[["Öffentliche Auftraggeber", "Müssen konforme E-Rechnungen annehmen und verarbeiten (seit 1. Oktober 2016)"], ["Lieferanten an den Staat", "Keine Ausstellungspflicht"], ["Private Unternehmen (B2B/B2C-Rechnungsstellung)", "Keine Pflicht jeglicher Art"], ["Persönliche B2C-Verkäufe (ab 2027)", "Echtzeitmeldung nach EET 2.0 — eine Umsatzerfassungspflicht, keine Rechnungspflicht"]]', 'Hier lohnt sich Präzision: Tschechien hat nie vorgeschrieben, dass jemand eine E-Rechnung versendet — nur, dass bestimmte öffentliche Stellen in der Lage sein müssen, eine anzunehmen, und, getrennt davon und ab 2027, dass persönliche Verkäufe in Echtzeit gemeldet werden.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Ce qui est réellement obligatoire aujourd''hui', '[["Pouvoirs adjudicateurs publics", "Doivent accepter et traiter les factures électroniques conformes (depuis le 1er octobre 2016)"], ["Fournisseurs de l''État", "Aucune obligation d''émission"], ["Entreprises privées (facturation B2B/B2C)", "Aucune obligation d''aucune sorte"], ["Ventes B2C en personne (à partir de 2027)", "Déclaration en temps réel au titre d''EET 2.0 — une obligation d''enregistrement des ventes, non de facturation"]]', 'Il convient d''être précis ici : la République tchèque n''a jamais imposé à quiconque d''envoyer une facture électronique — seulement que certains organismes publics soient capables d''en accepter une, et, séparément et à partir de 2027, que les ventes en personne soient déclarées en temps réel.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'EET 2.0 — una obligación real pero distinta', '[["Qué cubre", "Ventas presenciales B2C — pagos en efectivo, con tarjeta y por código QR"], ["Fecha de entrada en vigor", "1 de enero de 2027 (confirmada en el proyecto de ley aprobado)"], ["Exención", "Los pequeños autónomos con tributación a tanto alzado con una facturación anual inferior a 1.000.000 CZK pueden pagar un recargo para obtener la exención"], ["Estado legislativo", "Aprobado por la Cámara de Diputados; la aprobación del Senado y la firma presidencial siguen pendientes"]]', 'Esta es la única entrada de esta página que merece la pena vigilar para obtener una señal real sobre el calendario — la fecha de entrada en vigor está escrita en el proyecto de ley que ya aprobó la cámara baja, pero el Senado y el presidente aún tienen que dar su visto bueno antes de que sea ley completa.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'EET 2.0 — eine echte, aber andere Pflicht', '[["Was es abdeckt", "Persönliche B2C-Verkäufe — Bar-, Karten- und QR-Code-Zahlungen"], ["Inkrafttretensdatum", "1. Januar 2027 (im verabschiedeten Gesetzentwurf bestätigt)"], ["Befreiung", "Kleine Pauschalsteuerpflichtige mit einem Jahresumsatz unter 1.000.000 CZK können gegen einen Zuschlag eine Befreiung erhalten"], ["Gesetzgebungsstatus", "Vom Abgeordnetenhaus verabschiedet; Verabschiedung im Senat und Unterschrift des Präsidenten stehen noch aus"]]', 'Dies ist der einzige Eintrag auf dieser Seite, der ein echtes Signal zum Zeitplan wert ist zu beobachten — das Inkrafttretensdatum steht im Gesetzentwurf, den das Unterhaus bereits verabschiedet hat, aber Senat und Präsident müssen noch zustimmen, bevor es vollständig Gesetz ist.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'EET 2.0 — une obligation réelle mais distincte', '[["Ce qu''elle couvre", "Ventes B2C en personne — paiements en espèces, par carte et par code QR"], ["Date d''entrée en vigueur", "1er janvier 2027 (confirmée dans le projet de loi adopté)"], ["Exemption", "Les petits entrepreneurs au régime forfaitaire dont le chiffre d''affaires annuel est inférieur à 1 000 000 CZK peuvent payer une majoration pour obtenir une exemption"], ["Statut législatif", "Adopté par la Chambre des députés ; l''adoption par le Sénat et la signature présidentielle restent en attente"]]', 'C''est la seule entrée de cette page qui vaille la peine d''être surveillée pour un véritable signal sur le calendrier — la date d''entrée en vigueur est inscrite dans le projet de loi déjà adopté par la chambre basse, mais le Sénat et le président doivent encore donner leur accord avant que ce soit pleinement la loi.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🤝 Sin régimen sancionador de facturación electrónica nacional', NULL, NULL, 'No existe hoy ninguna sanción nacional por no emitir una factura electrónica en la República Checa, por la sencilla razón de que ninguna ley lo exige. La única obligación exigible — recibir facturas conformes — recae en los poderes adjudicadores públicos, no en los proveedores.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🤝 Kein inländisches E-Rechnungs-Sanktionsregime', NULL, NULL, 'Es gibt heute keine inländische Strafe für die Nichtausstellung einer E-Rechnung in Tschechien, aus dem einfachen Grund, dass kein Gesetz dies verlangt. Die einzige durchsetzbare Pflicht — die Annahme konformer Rechnungen — liegt bei öffentlichen Auftraggebern, nicht bei Lieferanten.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🤝 Aucun régime de sanctions national pour la facturation électronique', NULL, NULL, 'Il n''existe aujourd''hui aucune sanction nationale pour ne pas avoir émis de facture électronique en République tchèque, pour la simple raison qu''aucune loi ne l''exige. La seule obligation exécutoire — accepter des factures conformes — incombe aux pouvoirs adjudicateurs publics, non aux fournisseurs.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'penalties_related' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '💰 Las sanciones de EET 2.0 son reales — pero por el reporte de ventas, no por la facturación', NULL, NULL, 'Una vez que EET 2.0 entre en vigor, el incumplimiento de la obligación de reporte de ventas en tiempo real conlleva sanciones de hasta 500.000 CZK. Se trata de una cifra genuina y contrastada — pero es una multa por no reportar una venta, no por no emitir una factura electrónica. No confunda ambas cosas al evaluar su exposición.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '💰 EET 2.0s Strafen sind real — aber für die Umsatzmeldung, nicht die Rechnungsstellung', NULL, NULL, 'Sobald EET 2.0 in Kraft tritt, zieht die Nichteinhaltung der Echtzeit-Umsatzmeldepflicht Strafen von bis zu 500.000 CZK nach sich. Dies ist eine echte, belegte Zahl — aber es ist eine Strafe für das Versäumnis, einen Verkauf zu melden, nicht für das Versäumnis, eine E-Rechnung auszustellen. Verwechseln Sie die beiden nicht bei der Einschätzung Ihres Risikos.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '💰 Les sanctions d''EET 2.0 sont réelles — mais pour la déclaration des ventes, pas la facturation', NULL, NULL, 'Une fois EET 2.0 en vigueur, le non-respect de l''obligation de déclaration des ventes en temps réel entraîne des sanctions pouvant atteindre 500 000 CZK. Il s''agit d''un chiffre réel et sourcé — mais c''est une amende pour ne pas avoir déclaré une vente, non pour ne pas avoir émis une facture électronique. Ne confondez pas les deux lors de l''évaluation de votre exposition.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'penalties_related' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🇪🇺 El suelo de la UE que se aproxima', NULL, NULL, 'Con independencia de que la República Checa promulgue algún día su propio mandato nacional B2B, el requisito transfronterizo de ViDA es derecho de la UE confirmado desde el 1 de julio de 2030 — toda empresa checa que comercie intracomunitariamente B2B necesitará capacidad de facturación electrónica conforme con EN 16931 y de reporte digital para esas operaciones.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🇪🇺 Die nahende EU-Untergrenze', NULL, NULL, 'Unabhängig davon, ob Tschechien jemals seine eigene inländische B2B-Pflicht erlässt, ist ViDAs grenzüberschreitende Anforderung ab dem 1. Juli 2030 bestätigtes EU-Recht — jedes tschechische Unternehmen, das innergemeinschaftlichen B2B-Handel betreibt, benötigt für diese Umsätze EN-16931-konforme E-Rechnungs- und digitale Meldefähigkeit.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🇪🇺 Le plancher européen qui se rapproche', NULL, NULL, 'Indépendamment du fait que la République tchèque adopte un jour sa propre obligation nationale B2B, l''exigence transfrontalière de ViDA est un droit de l''UE confirmé à partir du 1er juillet 2030 — toute entreprise tchèque commerçant en B2B au sein de l''UE aura besoin d''une capacité de facturation électronique conforme à l''EN 16931 et de déclaration numérique pour ces transactions.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Czech Republic' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'es', 'Entienda lo que realmente es obligatorio para la facturación (muy poco)', 'Solo la capacidad de recepción de los poderes adjudicadores públicos es exigida por ley — no hay obligación de emisión para los proveedores, y hoy no existe ningún mandato B2B de ningún tipo.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Czech Republic' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'de', 'Verstehen Sie, was für die Rechnungsstellung tatsächlich verpflichtend ist (sehr wenig)', 'Gesetzlich vorgeschrieben ist nur die Empfangsfähigkeit öffentlicher Auftraggeber — es gibt keine Ausstellungspflicht für Lieferanten und heute keine B2B-Pflicht jeglicher Art.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Czech Republic' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'fr', 'Comprenez ce qui est réellement obligatoire pour la facturation (très peu)', 'Seule la capacité de réception des pouvoirs adjudicateurs publics est exigée par la loi — il n''y a aucune obligation d''émission pour les fournisseurs, et aucune obligation B2B d''aucune sorte aujourd''hui.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Czech Republic' AND s.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'es', 'Si tiene comercio minorista, hostelería o servicios presenciales, prepárese para EET 2.0', 'El reporte en tiempo real de las ventas en efectivo, con tarjeta y por QR se vuelve obligatorio a partir del 1 de enero de 2027 — una obligación distinta de la facturación, pero real, con sanciones de hasta 500.000 CZK.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Czech Republic' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'de', 'Wenn Sie stationären Einzelhandel, Gastgewerbe oder Dienstleistungen betreiben, bereiten Sie sich auf EET 2.0 vor', 'Die Echtzeitmeldung von Bar-, Karten- und QR-Code-Verkäufen wird ab dem 1. Januar 2027 verpflichtend — eine von der Rechnungsstellung getrennte, aber echte Pflicht mit Strafen von bis zu 500.000 CZK.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Czech Republic' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'fr', 'Si vous exercez dans le commerce de détail, l''hôtellerie-restauration ou les services en personne, préparez-vous à EET 2.0', 'La déclaration en temps réel des ventes en espèces, par carte et par QR devient obligatoire à partir du 1er janvier 2027 — une obligation distincte de la facturation, mais réelle, avec des sanctions pouvant atteindre 500 000 CZK.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Czech Republic' AND s.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'es', 'Si abastece a organismos públicos checos, considere la facturación electrónica voluntaria', 'Enviar facturas electrónicas estructuradas a través de NEN en EDIFACT, UBL 2.1 o ISDOC puede agilizar el procesamiento aunque no sea obligatorio — una forma de bajo coste de adelantarse a un futuro mandato.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Czech Republic' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'de', 'Wenn Sie tschechische öffentliche Stellen belieferen, erwägen Sie die freiwillige E-Rechnung', 'Der Versand strukturierter E-Rechnungen über NEN in EDIFACT, UBL 2.1 oder ISDOC kann die Bearbeitung beschleunigen, auch wenn es nicht vorgeschrieben ist — eine kostengünstige Möglichkeit, einer künftigen Pflicht vorzugreifen.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Czech Republic' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'fr', 'Si vous fournissez des organismes publics tchèques, envisagez la facturation électronique volontaire', 'L''envoi de factures électroniques structurées via NEN en EDIFACT, UBL 2.1 ou ISDOC peut accélérer le traitement même si ce n''est pas obligatoire — un moyen peu coûteux de prendre les devants sur une future obligation.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Czech Republic' AND s.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'es', 'Prepárese para el suelo transfronterizo confirmado de 2030 en cualquier caso', 'Toda empresa que comercie transfronterizamente dentro de la UE necesita capacidad de facturación electrónica EN 16931 y de reporte digital a partir del 1 de julio de 2030 — esta fecha está fijada por la directiva de la UE, no por la discreción checa.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Czech Republic' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'de', 'Bereiten Sie sich unabhängig davon auf die bestätigte grenzüberschreitende Untergrenze von 2030 vor', 'Jedes Unternehmen, das grenzüberschreitend innerhalb der EU Handel betreibt, benötigt ab dem 1. Juli 2030 EN-16931-E-Rechnungs- und digitale Meldefähigkeit — dieses Datum ist durch EU-Richtlinie festgelegt, nicht durch tschechisches Ermessen.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Czech Republic' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'fr', 'Préparez-vous de toute façon au plancher transfrontalier confirmé de 2030', 'Toute entreprise commerçant à l''échelle transfrontalière au sein de l''UE a besoin d''une capacité de facturation électronique EN 16931 et de déclaration numérique à partir du 1er juillet 2030 — cette date est fixée par la directive européenne, non par la discrétion tchèque.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Czech Republic' AND s.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'es', 'Vigile la aprobación del Senado y la firma presidencial de EET 2.0', 'La Cámara de Diputados ha aprobado el proyecto de ley y su fecha del 1 de enero de 2027, pero el Senado y el presidente Petr Pavel aún deben dar su visto bueno antes de que quede plenamente promulgado.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Czech Republic' AND s.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'de', 'Beobachten Sie die Verabschiedung im Senat und die Unterschrift des Präsidenten für EET 2.0', 'Das Abgeordnetenhaus hat den Gesetzentwurf und sein Datum vom 1. Januar 2027 verabschiedet, aber Senat und Präsident Petr Pavel müssen noch zustimmen, bevor es vollständig in Kraft tritt.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Czech Republic' AND s.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'fr', 'Surveillez l''adoption par le Sénat et la signature présidentielle d''EET 2.0', 'La Chambre des députés a adopté le projet de loi et sa date du 1er janvier 2027, mais le Sénat et le président Petr Pavel doivent encore donner leur accord avant qu''il ne soit pleinement promulgué.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Czech Republic' AND s.sort_order = 4;

